import{z as i,x as o,o as B,c,q as t,j as s,D as r,d as E,s as l,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"exactly-once","description":"","frontmatter":{"title":"exactly-once","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/stream-exactly-once.md","filePath":"cs/stream-exactly-once.md","lastUpdated":1791063341000}'),d={name:"cs/stream-exactly-once.md"};function p(D,a,m,f,h,F){const A=o("Mermaid");return B(),c("div",null,[a[2]||(a[2]=t('<h1 id="exactly-once" tabindex="-1">exactly-once <a class="header-anchor" href="#exactly-once" aria-label="Permalink to &quot;exactly-once&quot;">​</a></h1><div class="epigraph"><p>端到端恰好一次从来不是「消息只送一次」，而是「效果只发生一次」：重复的投递被快照、事务与幂等吸收，结果与只算一次不可区分。</p><footer>—— 据 Chandy and Lamport, 1985；Kafka 事务与 Flink 检查点公开设计整理</footer></div><p><a href="/cs/stream-watermark">上一课</a>给了事件时间进度钟，窗口可以按时关了。缺口是故障：进程挂在半窗状态上，重启后同一段输入再算一遍，窗口结果被写两次，撤回也救不回对下游的重复冲击。本课钉流系统恰好一次的机制层：它的两条实现路线与各自的代价。投递次数不等于业务效果次数，这条已在<a href="/cs/delivery-semantics">投递语义</a>与主干<a href="/cs/exactly-once">恰好一次</a>课立过，本课不重讲定义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>重复与丢失分布在三处：输入可能重投（重放本就是恢复手段），算子状态可能回退，sink 可能重复写。恰好一次要求三者原子地进退：要么都停在某个一致点，要么都前进。难点在机制——这是一个持续运行、永不停止的分布式计算，怎么给它拍出「所有算子停在同一逻辑时刻」的快照？全局停机牺牲可用性；各拍各的，快照之间在途记录就成了没人管的缝隙。</p><p><span class="marginnote">快照要的不是「同一墙钟时刻」，而是因果一致：快照里在途的记录，恢复后必须还能重放到位。Chandy–Lamport 的标记协议给出的正是这种一致性，与墙钟无关。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>路线一：一致性快照加重放。<a href="/cs/chandy-lamport">Chandy–Lamport 快照</a>用标记消息记录在途内容；Flink 的异步屏障快照把标记（barrier）随数据流周期注入，算子收齐全部输入的 barrier 后把状态异步写进快照存储，barrier 对齐使整张作业图的快照等价于一个逻辑时刻。故障后从上一个检查点恢复，输入按偏移<a href="/cs/kafka-log">重放</a>，重放无害的前提是确定性重算。路线二：日志事务。把消费-变换-生产包进一个 <a href="/cs/kafka-log">Kafka 事务</a>，输出与偏移提交同生共死，下游读已提交前缀。sink 收口两条：事务 sink——对支持它的外部系统走<a href="/cs/two-pc">两阶段提交</a>；或幂等 upsert——用「窗口 + 键 + 版本」做<a href="/cs/idempotency-keys">幂等键</a>。</p>',8)),(B(),s(n,null,{default:r(()=>[l(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22barrier%20%E9%9A%8F%E6%95%B0%E6%8D%AE%E6%B5%81%E5%91%A8%E6%9C%9F%E6%B3%A8%E5%85%A5%22%5D%20--%3E%20ALIGN%5B%22%E5%AF%B9%E9%BD%90%EF%BC%9A%E6%94%B6%E9%BD%90%E6%89%80%E6%9C%89%E8%BE%93%E5%85%A5%E7%9A%84%20barrier%22%5D%0A%20%20ALIGN%20--%3E%20SNAP%5B%22%E7%8A%B6%E6%80%81%E5%BC%82%E6%AD%A5%E5%86%99%E5%BF%AB%E7%85%A7%E5%AD%98%E5%82%A8%22%5D%0A%20%20SNAP%20--%3E%20CKPT%5B%22%E8%BE%93%E5%85%A5%E5%81%8F%E7%A7%BB%20%2B%20%E7%8A%B6%E6%80%81%E5%8E%9F%E5%AD%90%E6%8F%90%E4%BA%A4%22%5D%0A%20%20FAIL%5B%22%E8%BF%9B%E7%A8%8B%E6%8C%82%22%5D%20--%3E%20REST%5B%22%E4%BB%8E%E6%A3%80%E6%9F%A5%E7%82%B9%E6%81%A2%E5%A4%8D%EF%BC%9A%E6%8C%89%E5%81%8F%E7%A7%BB%E9%87%8D%E6%94%BE%22%5D%0A%20%20REST%20--%3E%20SINK%5B%22%E4%BA%8B%E5%8A%A1%20sink%20%2F%20%E5%B9%82%E7%AD%89%20upsert%20%E6%94%B6%E5%8F%A3%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("对齐有代价：收齐 barrier 意味着快的通道等慢的，背压严重时整张图被最慢边拖住，检查点超时失败。非对齐 barrier 把在途记录一并写进快照：快照更大、恢复更慢，但省掉对齐停顿——背压场景里这是唯一能按时出检查点的模式。检查点间隔就是 RPO：间隔内的进度像"),e("a",{href:"/cs/group-commit"},"异步提交"),E("，故障后重放，重放本身无害，无害的前提是效果幂等。确定性是隐藏前提：恢复后重算，外部时钟、随机数、跨通道竞争都会让第二次结果偏离第一次，恰好一次退化成恰好一次「送达」，还得靠撤回或幂等兜底。Kafka 事务只覆盖 Kafka 下游：跨异构 sink 没有银弹，外部副作用（发邮件）只能幂等。")],-1)),a[5]||(a[5]=e("p",null,"对齐与非对齐两种拍快照方式各有各的债，选型就是在「等」与「拍重」之间挑更付得起的那个。",-1)),(B(),s(n,null,{default:r(()=>[l(A,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20BR%5B%22barrier%20%E5%88%B0%E8%BE%BE%E6%9F%90%E7%AE%97%E5%AD%90%22%5D%20--%3E%20Q%7B%22%E9%80%89%E5%AF%B9%E9%BD%90%E8%BF%98%E6%98%AF%E9%9D%9E%E5%AF%B9%E9%BD%90%3F%22%7D%0A%20%20Q%20--%20%22%E5%AF%B9%E9%BD%90%22%20--%3E%20WA%5B%22%E7%BC%93%E4%BD%8F%E5%BF%AB%E9%80%9A%E9%81%93%E7%AD%89%E6%9C%80%E6%85%A2%E8%BE%93%E5%85%A5%22%5D%0A%20%20WA%20--%3E%20PAY%5B%22%E4%BB%A3%E4%BB%B7%3A%20%E8%83%8C%E5%8E%8B%E6%97%B6%E6%A3%80%E6%9F%A5%E7%82%B9%E8%B6%85%E6%97%B6%22%5D%0A%20%20WA%20--%3E%20SN1%5B%22%E5%BF%AB%E7%85%A7%E5%B0%8F%3A%20%E5%8F%AA%E5%90%AB%E7%8A%B6%E6%80%81%22%5D%0A%20%20Q%20--%20%22%E9%9D%9E%E5%AF%B9%E9%BD%90%22%20--%3E%20INJ%5B%22%E5%9C%A8%E9%80%94%E8%AE%B0%E5%BD%95%E4%B8%80%E5%B9%B6%E5%86%99%E8%BF%9B%E5%BF%AB%E7%85%A7%22%5D%0A%20%20INJ%20--%3E%20PAY2%5B%22%E4%BB%A3%E4%BB%B7%3A%20%E5%BF%AB%E7%85%A7%E5%A4%A7%20%E6%81%A2%E5%A4%8D%E6%85%A2%22%5D%0A%20%20INJ%20--%3E%20SN2%5B%22%E6%94%B6%E7%9B%8A%3A%20%E4%B8%8D%E5%81%9C%E9%A1%BF%20%E6%8C%89%E6%97%B6%E5%87%BA%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%0A%20%20SN1%20--%3E%20OK%5B%22%E4%B8%A4%E7%A7%8D%E9%83%BD%E4%BF%9D%E8%AF%81%E5%9B%A0%E6%9E%9C%E4%B8%80%E8%87%B4%22%5D%0A%20%20SN2%20--%3E%20OK%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">常见误区：初学者容易以为「exactly-once 引擎 = 消息绝不重复发送」。实际上 Kafka、Flink 在故障后都会重放或重投同一段数据，恰好一次的成立完全依赖下游用事务、幂等键或快照恢复把重复效果吸收掉——引擎管住的是状态，管不住外部世界。</span></p><p><span class="marginnote">数字实例：检查点间隔 \\(30\\ s\\) 意味着故障后最多重算 \\(30\\) 秒的输入（RPO=\\(30\\ s\\)）；把间隔缩到 \\(5\\ s\\)，重算量缩小到六分之一，但每分钟要拍 \\(12\\) 次快照、快照存储与网络开销翻六倍——间隔的选择就是 RPO 与开销的折中。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>检查点不等于备份：它覆盖进程故障，不覆盖逻辑错误——写错的窗口结果会被一致地快照下来，回滚到正确值要靠重算历史或版本回退。本课不提供绕过幂等去刷外部系统的办法，也不比较各引擎检查点实现的性能数字。后课默认：join 与状态都活在这套快照协议下，故障重放不产生重复效果是已付的成本。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>恰好一次是效果幂等：重放、重投不改变可观测结果。</li><li>路线一是快照加重放（barrier 对齐或非对齐），路线二是日志事务（Kafka）。</li><li>确定性重算是重放的前提；非确定算子会把「恰好一次」降级为「恰好一次送达」。</li><li>检查点间隔即 RPO；sink 靠两阶段提交或幂等键收口，跨异构 sink 无银弹。</li><li>出处：Chandy and Lamport, TOCS 1985；Carbone et al., 2015（异步屏障快照）；Kreps et al., 2011。</li></ul>',6))])}const C=i(d,[["render",p]]);export{u as __pageData,C as default};
